import type {TestContext} from 'node:test';
import {randomUUID} from 'node:crypto';
import {mkdirSync} from 'node:fs';
import {join} from 'node:path';
import {fixture,hire,objective} from '../../helpers.js';
import type {Worker} from '../../../src/domain/model.js';
import {FixtureClock} from '../../../src/control/investment.js';
import {FiniteJournal} from '../../../src/control/usage/finite-journal.js';
import {hash} from '../../../src/domain/investment/identity.js';
import type {FiniteHQPolicy} from '../../../src/domain/usage/policy.js';
import {ZERO} from '../../../src/domain/usage/tokens.js';
import {MarketStore} from '../../../src/control/market/store.js';
import {normalizePrice} from '../../../src/domain/market/normalize.js';
import type {CalendarEvidence,InstrumentIdentity,SourcePolicy} from '../../../src/domain/market/types.js';
export function finiteFixture(t?:Pick<TestContext,'mock'>){
 const clock=new FixtureClock('2026-10-12T10:00:00.000Z');
 // Authored sessions and shared evidence use one synthetic clock; real timers stay real.
 if(t){t.mock.timers.enable({apis:['Date'],now:Date.parse(clock.now())});const set=clock.set.bind(clock);t.mock.method(clock,'set',(at:string)=>{set(at);t.mock.timers.setTime(Date.parse(clock.now()));});}
 const f=fixture();f.company.assignObjective(objective);const x=f.company.claimNext()!,first=x.worker,second=f.company.callTool(x.context,'hire','hire_worker',hire) as Worker;f.company.finish(x.execution.execution_id,{status:'completed',summary:'Synthetic roster setup, no inference'});
 f.store.run("UPDATE workers SET execution_priority='high' WHERE worker_id=?",first.worker_id);
 f.company.mandates.clock={now:()=>Date.parse(clock.now())};
 const policy:FiniteHQPolicy={mode:'credit_approved_finite_hq',authorityId:'finite_'+randomUUID(),maxRun:10,maxRolling24h:8,maxWorker:7,maxCycle:7,maxDay:7,maxDurationMs:300000,maxConcurrent:1,uncertainRetries:0,existingCreditsApproved:true,providerRetriesAccepted:true};
 const input={mandate:'Evaluate a finite synthetic portfolio and learn from prior outcomes',desiredOutput:'Consider HOLD and alternative paper actions, preserve uncertainty',constraints:'Invented fixtures only; no genuine employee execution',participants:[{workerId:first.worker_id,name:'Fixture allocator',responsibility:'Propose and submit scoped paper actions'},{workerId:second.worker_id,name:'Fixture challenger',responsibility:'Independently challenge exact paper proposals'}],proposers:[first.worker_id],reviewers:[second.worker_id],submitters:[first.worker_id],facilitatorId:first.worker_id,synthesizerId:first.worker_id,sessions:['2026-10-13','2026-10-15'],start:'at_consent',initialCapital:'10000',commission:'0',slippageBps:0,positionLimitBps:5000,sectorLimitBps:7000,drawdownAttentionBps:2000,policy,aiProfile:{model:'fake-model',reasoningEffort:'medium',serviceTier:'default',cliVersion:'0.157.0'},researchMinutes:60,maxProposals:10,maxOrders:10};
 const preview=()=>f.company.investmentSetup.preview(input),consent=(p=preview(),receiptId=randomUUID())=>f.company.investmentSetup.consent({previewId:p.previewId,digest:p.digest,receiptId});
 const authorize=(result:ReturnType<typeof consent>,approvedAccount={accountFingerprint:hash('fake-private-account'),routingFingerprint:hash('fake-official-route')})=>{const dir=join(f.company.dataDir,'external-fixture'),custody=join(f.company.dataDir,'independent-fixture');mkdirSync(dir,{mode:0o700});mkdirSync(custody,{mode:0o700});const journal=FiniteJournal.createFixture(join(dir,'authority.sqlite'),join(custody,'checkpoint.json'),clock.now());f.company.finiteHQ.attach(journal);const account=approvedAccount,attestation={authorityId:policy.authorityId,runId:result.configuration.runId,accountFingerprint:account.accountFingerprint,ownerId:'human',confirmedAt:clock.now(),reloadOff:true as const,evidenceHash:hash('explicit fake owner confirmation')};f.company.finiteHQ.approve(result.scope.scopeId,account,{ownerId:'human',receiptHash:hash('fake-only-approval'),approvedAt:clock.now()},attestation);return {journal,account,attestation};};
 return {...f,first,second,clock,policy,input,preview,consent,authorize};
}
export function runningFiniteFixture(t?:Pick<TestContext,'mock'>){
 const f=finiteFixture(t),result=f.consent(),authority=f.authorize(result),c=f.company,loop=c.investmentLoop;
 c.investmentTeam.runtime={type:'fake',supportsInterrupt:true,run:async()=>{throw Error('Ordinary runtime forbidden');},finiteHQPolicySupported:()=>true,runFiniteHQInvestment:async()=>{throw Error('Manual fake test never starts a provider');}};
 const control=(action:string)=>loop.control({loopId:result.loop.loopId,action,digest:result.loop.digest,receiptId:randomUUID(),orderId:null});control('start');
 const occurrences=()=>loop.occurrences(loop.get(result.loop.loopId));
 const renew=()=>{authority.attestation.confirmedAt=f.clock.now();c.finiteHQ.renew(authority.attestation);};
 const session=(index:number)=>{f.clock.set(occurrences().filter(o=>o.stage==='research')[index]!.due_at);renew();loop.tick();};
 const claim=()=>{const x=c.claimWorkNext();if(!x||x.origin!=='conversation')throw Error('Finite claim missing: '+JSON.stringify({loop:loop.get(result.loop.loopId),group:c.discussions.group(result.scope.envelope.groupId),authority:c.finiteHQ.inspect(result.scope.scopeId)}));
  c.conversations.prepareBinding(x.context,c.conversations.binding(x.context)??{worker_id:x.worker.worker_id,runtime_type:'fake',workspace_path:x.worker.workspace_path,runtime_reference:'fake_'+randomUUID(),created_at:f.clock.now()});c.conversations.activateBinding(x.context);c.conversations.context(x.context);c.recordRuntimeConfig(x.context,{model:f.input.aiProfile.model,reasoning_effort:f.input.aiProfile.reasoningEffort,runtime_version:'codex-cli 0.157.0',runtime_adapter:'fake',execution_priority:x.worker.execution_priority});
  const threadId=c.conversations.binding(x.context)!.runtime_reference,turnId='turn_'+randomUUID();c.aiUsage.observe(x.execution.execution_id,{kind:'start',identity:{threadId,model:f.input.aiProfile.model,provider:'openai',serviceTier:'default',freshThread:true}});c.aiUsage.observe(x.execution.execution_id,{kind:'turn',threadId,turnId});c.investmentActivity.admit(x.context,{threadId,model:f.input.aiProfile.model,...authority.account,eligibility:{authMode:'chatgpt',provider:'openai',planType:'pro',paidCredits:'existing_approved',ordinaryUsageAllowed:false,creditUsageAllowed:true}});authority.journal.transmit(x.execution.execution_id,threadId,{fingerprint:authority.account.accountFingerprint,routingFingerprint:authority.account.routingFingerprint},f.clock.now());return {...x,threadId,turnId};};
 const call=(x:ReturnType<typeof claim>,name:string,args:unknown)=>c.conversations.callTool(x.context,randomUUID(),name,args) as any;
 const read=(x:ReturnType<typeof claim>)=>call(x,'read_group_record',{record_id:result.evidence.evidence_id,offset:0});
 const finish=(x:ReturnType<typeof claim>,complete=true,settled=true)=>{if(complete)c.aiUsage.observe(x.execution.execution_id,{kind:'response',threadId:x.threadId,turnId:x.turnId,responseId:'response_'+x.execution.execution_id,usage:{...ZERO,inputTokens:100,outputTokens:20,totalTokens:120}});c.finish(x.execution.execution_id,{status:'completed',summary:'Deterministic fixture, no inference',settled});};
 const contribute=(x:ReturnType<typeof claim>,refs:string[]=[])=>{read(x);return call(x,'submit_contribution',{body:'Synthetic fixture compares the approved alternatives with the supplied evidence.',contribution_ids:refs,evidence_ids:[result.evidence.evidence_id],questions:[],answers:[]});};
 const facilitate=(x:ReturnType<typeof claim>,turns:{worker_id:string;prompt:string;contribution_ids:string[];evidence_ids:string[]}[]=[])=>call(x,'facilitate_discussion',{body:'Synthetic bounded progression selected by fake provider.',action:turns.length?'discuss':'synthesize',turns});
 const proposal=(x:ReturnType<typeof claim>,id:string,action='HOLD',sessionIndex=0)=>{read(x);return call(x,'paper_propose',{decisionId:id,revision:1,action,marketObservationIds:[],order:action==='HOLD'?null:{instrumentId:'SYNTHA',side:action,quantity:'2',priceGuard:action==='BUY'?'110':'90',targetSession:f.input.sessions[sessionIndex]},rationale:'Synthetic evidence supports this test branch',alternatives:['HOLD until better evidence'],risks:['Invented fixture uncertainty'],invalidationCondition:'A changed observation invalidates the premise',contributionIds:[],evidenceIds:[result.evidence.evidence_id]}).proposal;};
 const review=(x:ReturnType<typeof claim>,p:any)=>{read(x);call(x,'paper_read_proposal',{proposalId:p.proposal_id});return call(x,'paper_review',{proposalId:p.proposal_id,proposalHash:p.proposal_hash,disposition:'approve',rationale:'Independent synthetic branch review',dissent:[],evidenceIds:[result.evidence.evidence_id]}).review;};
 const submit=(x:ReturnType<typeof claim>,p:any,r:any)=>{read(x);call(x,'paper_read_proposal',{proposalId:p.proposal_id});return call(x,'paper_submit',{proposalId:p.proposal_id,proposalHash:p.proposal_hash,reviewId:r.review_id});};
 const price=(id:string,index:number,field:'regular_open'|'regular_close',value='100')=>{const m=new MarketStore(f.store),config=result.configuration,calendar=m.get<CalendarEvidence>(config.calendar.version,'calendar'),p=m.get<SourcePolicy>(config.marketPolicy.id,'policy'),i=m.get<InstrumentIdentity>(id,'instrument'),s=calendar.calendar.sessions[index]!,body=JSON.stringify({schema:'synthetic-price-v1',symbol:i.symbols[0]!.symbol,venue:'XNYS',currency:'USD',field,value,adjustment:'raw',session:s.date,marketAt:field==='regular_open'?s.open:s.close,availableAt:null,sourceId:`${id}-${s.date}-${field}`,sourceVersion:1,status:'verified',correctionOf:null}),e=normalizePrice(body,{instrumentId:id,session:s.date,field},p,i,calendar,f.clock.now(),m.prices());m.put(e.id,'price',e,f.clock.now());return e;};
 const financial=(index:number)=>{const config=result.configuration,s=config.calendar.sessions[index];f.clock.set(s.open);for(const id of ['SYNTHA','SYNETF'])price(id,index,'regular_open');loop.tick();f.clock.set(s.close);for(const id of ['SYNTHA','SYNETF'])price(id,index,'regular_close');loop.tick();};
 return {...f,result,authority,control,occurrences,renew,session,claim,call,read,finish,contribute,facilitate,proposal,review,submit,price,financial,close:()=>{authority.journal.close();f.close();}};
}
